#!/usr/bin/env bash
# Prove the committed generated UI bundles match their sources.
#
#   scripts/check-generated.sh
#
# internal/ui/app.js and internal/ui/app.css are generated by
# `go generate ./internal/ui` from internal/ui/js and internal/ui/css. They are
# committed, so a source change that was not regenerated, or a hand edit to a
# generated file, must fail here instead of shipping.
#
# Success leaves the working tree as it was: the regenerated bytes are
# identical, so only the modification times change. Failure keeps the
# regenerated files on disk so the developer can inspect and commit them.
#
# Environment:
#   GENERATE_TIMEOUT  seconds allowed for go generate (default 300)
set -euo pipefail
# shellcheck disable=SC1091
source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"
cd "$ROOT"

GENERATE_TIMEOUT="${GENERATE_TIMEOUT:-300}"
[[ "$GENERATE_TIMEOUT" =~ ^[1-9][0-9]*$ ]] || die "GENERATE_TIMEOUT must be a positive whole number of seconds"

generated=(internal/ui/app.js internal/ui/app.css)
regenerate="go generate ./internal/ui"

say "generated UI bundles (app.js, app.css)"

command -v timeout >/dev/null 2>&1 || die "timeout (coreutils) is required to bound go generate"
for file in "${generated[@]}"; do
	[[ -f "$file" ]] || die "generated file is missing: $file (run: $regenerate)"
done

declare -A before=() after=()
while read -r sum file; do
	before[$file]="$sum"
done < <(sha256sum "${generated[@]}")

status=0
timeout "$GENERATE_TIMEOUT" "$GO" generate ./internal/ui || status=$?
if ((status == 124)); then
	die "$regenerate timed out after ${GENERATE_TIMEOUT}s; the generated files may be partially rewritten"
elif ((status != 0)); then
	die "$regenerate failed with exit status $status; the generated files may be partially rewritten"
fi

while read -r sum file; do
	after[$file]="$sum"
done < <(sha256sum "${generated[@]}")

changed=()
for file in "${generated[@]}"; do
	if [[ "${before[$file]}" != "${after[$file]}" ]]; then
		changed+=("$file")
	fi
done

if ((${#changed[@]})); then
	printf 'error: the committed generated UI does not match its sources\n' >&2
	for file in "${changed[@]}"; do
		printf '       stale or hand-edited: %s\n' "$file" >&2
	done
	printf '       regenerate it with: %s\n' "$regenerate" >&2
	printf '       the regenerated files are left on disk; inspect and commit them\n' >&2
	printf '       rerun this gate with: scripts/check-generated.sh\n' >&2
	exit 1
fi

say "generated UI bundles match their sources"
